// ==========================================
// 1. CONFIGURACIÓN Y MAPEO DE DATOS (N8N)
// ==========================================

const CLIENT_NAME = $('Start').first().json.empresa; 
const DATE_START =  $('Start').first().json.fecha_inicio_formato || "Inicio";
const DATE_STOP =   $('Start').first().json.fecha_fin_formato || "Fin";

// B. PROCESAMIENTO DE INSIGHTS DE IA
let aiInsights = {
    best_performance_text: "Análisis pendiente...",
    volume_text: "Análisis pendiente...",
    funnel_text: "Análisis pendiente..."
};

try {
    const aiRawContent = $input.first().json.choices[0].message.content;
    const cleanJsonString = aiRawContent.replace(/```json\n|\n```/g, '').trim();
    aiInsights = JSON.parse(cleanJsonString);
} catch (error) {
    console.log("Error parseando Insights de IA:", error);
}

// C. DATOS DE CAMPAÑAS
const inputData = $('Aggregate1').first().json.data || []; 


// ==========================================
// 2. LÓGICA DE PROCESAMIENTO 
// ==========================================

// --- LÓGICA DE FASES (NUEVO) ---
const PHASE_LIBRARY = {
    "FASE 1": {
        title: "FASE 1 – ENGANCHAR",
        desc: "En esta fase ponemos tu negocio frente a las personas correctas y hacemos que te reconozcan. Creamos campañas de reconocimiento y tráfico con ganchos rápidos que captan atención en los primeros segundos. <strong>¿Para qué sirve?</strong> Para que el público empiece a identificar tu marca, confiar y no sentir que le están vendiendo algo de golpe. Sin esta fase, los anuncios de venta se sienten forzados y salen más caros."
    },
    "FASE 2": {
        title: "FASE 2 – SOLUCIONAR",
        desc: "Aquí es donde vamos directo a vender. Activamos múltiples campañas enfocadas en mostrar el problema del cliente y cómo tu servicio o producto lo soluciona, usando imágenes, videos, carruseles y pruebas constantes. Todos los días analizamos resultados, apagamos lo que no funciona y duplicamos lo que sí. <strong>¿Para qué sirve?</strong> Para generar ventas y citas reales, no likes ni mensajes vacíos."
    },
    "FASE 3": {
        title: "FASE 3 – REMARKETING FIDELIZAR",
        desc: "En esta fase atacamos a las personas que ya te vieron, interactuaron o preguntaron, pero no compraron. Les mostramos testimonios, casos reales, validadores y mensajes más directos para cerrar la decisión. <strong>¿Para qué sirve?</strong> Para convertir indecisos en clientes y recuperar dinero que normalmente se pierde si no se les da seguimiento estratégico."
    },
    "FASE 4": {
        title: "FASE 4 – REMARKETING ENVOLVER",
        desc: "Aquí mantenemos tu marca viva en la mente del prospecto. Mostramos quién eres, dónde estás, tu historia y tu equipo, con videos que refuerzan confianza y cercanía. <strong>¿Para qué sirve?</strong> Para que cuando el cliente esté listo para comprar, no dude ni compare tanto, porque ya te siente como la opción correcta."
    },
    "FASE 5": {
        title: "FASE 5 – ESCALAR",
        desc: "Cuando identificamos anuncios ganadores, entramos en esta fase. Aumentamos presupuesto de forma controlada, duplicamos campañas en nuevas audiencias y aprovechamos los picos de rendimiento. <strong>¿Para qué sirve?</strong> Para multiplicar resultados sin romper lo que ya funciona y hacer crecer el negocio de forma sostenida, no por suerte."
    },
    "FASE 6": {
        title: "FASE 6 – AUTOMATIZAR",
        desc: "Esta fase convierte la publicidad en un sistema constante. Medimos métricas clave cada semana, aplicamos reglas claras y lanzamos campañas nuevas de forma continua. Nada se deja al azar. <strong>¿Para qué sirve?</strong> Para que el negocio no dependa de improvisaciones, tenga flujo constante de clientes y pueda escalar con orden y previsibilidad."
    }
};

let activePhasesHTML = "";
const detectedPhases = new Set();

// Detectar fases activas en base al nombre de la campaña
inputData.forEach(c => {
    const name = c.name.toUpperCase();
    if (name.includes("FASE 1")) detectedPhases.add("FASE 1");
    if (name.includes("FASE 2")) detectedPhases.add("FASE 2");
    if (name.includes("FASE 3")) detectedPhases.add("FASE 3");
    if (name.includes("FASE 4")) detectedPhases.add("FASE 4");
    if (name.includes("FASE 5")) detectedPhases.add("FASE 5");
    if (name.includes("FASE 6")) detectedPhases.add("FASE 6");
});

// Generar HTML solo si hay fases detectadas
if (detectedPhases.size > 0) {
    // Ordenar fases (1, 2, 3...)
    const sortedPhases = Array.from(detectedPhases).sort();

    sortedPhases.forEach(phaseKey => {
        const info = PHASE_LIBRARY[phaseKey];
        activePhasesHTML += `
            <div class="phase-card">
                <div class="phase-title">${info.title}</div>
                <div class="phase-desc">${info.desc}</div>
            </div>
        `;
    });
} else {
    // Fallback si no detecta fases explícitas en nombres
    activePhasesHTML = `<div class="phase-desc" style="text-align:center; padding: 20px;">Análisis de estrategia general activo.</div>`;
}


// --- LÓGICA DE MÉTRICAS (EXISTENTE) ---
const metrics = {
    performance: { results: 0, spend: 0 },
    awareness: { reach: 0, impressions: 0, spend: 0 },
    total: { spend: 0, reach: 0, impressions: 0 }
};

let tableRowsHTML = "";

function getFriendlyIndicatorName(rawIndicator) {
    if (!rawIndicator) return "Desconocido";
    const ind = rawIndicator.toLowerCase();
    if (ind.includes('messaging_conversation_started')) return "Mensajes";
    if (ind.includes('lead')) return "Leads";
    if (ind.includes('purchase')) return "Compras";
    if (ind.includes('reach')) return "Alcance";
    if (ind.includes('thruplay') || ind.includes('video_view')) return "ThruPlay";
    if (ind.includes('link_click')) return "Tráfico";
    if (ind.includes('engagement') || ind.includes('post_reaction')) return "Interacción";
    return "Resultado";
}

inputData.forEach(campaign => {
    const insights = campaign.insights?.data?.[0] || {};
    const obj = campaign.objective || "UNKNOWN";

    const resultVal = parseFloat(insights.results?.[0]?.values?.[0]?.value || 0);
    const spendVal = parseFloat(insights.spend || 0);
    const reachVal = parseInt(insights.reach || 0);
    const impVal = parseInt(insights.impressions || 0);
    const cprVal = parseFloat(insights.cost_per_result?.[0]?.values?.[0]?.value || 0);
    const rawIndicator = insights.results?.[0]?.indicator || "";

    let isPerformance = false;
    if (obj === 'OUTCOME_SALES' || obj === 'OUTCOME_LEADS') {
        isPerformance = true;
    } else if (obj === 'OUTCOME_ENGAGEMENT') {
        if (rawIndicator.includes('messaging') || rawIndicator.includes('lead')) {
            isPerformance = true;
        }
    }

    metrics.total.spend += spendVal;
    metrics.total.reach += reachVal; 
    metrics.total.impressions += impVal;

    if (isPerformance) {
        metrics.performance.results += resultVal;
        metrics.performance.spend += spendVal;
    } else {
        metrics.awareness.reach += reachVal;
        metrics.awareness.impressions += impVal;
        metrics.awareness.spend += spendVal;
    }

    let badgeText = getFriendlyIndicatorName(rawIndicator);
    let badgeClass = isPerformance ? "status-perf" : "status-brand";
    let resultTinyLabel = isPerformance ? "Conversiones" : "Eventos";
    let campNameShort = (campaign.name || "Sin Nombre").split('|')[0];

    tableRowsHTML += `
        <tr>
            <td>
                <div class="camp-name">${campNameShort}...</div>
                <div class="camp-obj">${obj.replace('OUTCOME_', '')}</div>
            </td>
            <td><span class="status-badge ${badgeClass}">${badgeText}</span></td>
            <td>
                <strong>${resultVal.toLocaleString()}</strong>
                <div class="tiny-label">${resultTinyLabel}</div>
            </td>
            <td>$${cprVal.toFixed(2)}</td>
            <td>$${spendVal.toFixed(2)}</td>
        </tr>
    `;
});

const realCPA = metrics.performance.results > 0 
    ? (metrics.performance.spend / metrics.performance.results) 
    : 0;

const accountCPM = metrics.total.impressions > 0 
    ? (metrics.total.spend / metrics.total.impressions) * 1000 
    : 0;


// ==========================================
// 3. GENERACIÓN DE HTML (Diseño Legal PDF)
// ==========================================
const htmlContent = `
