<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Reporte - ${CLIENT_NAME}</title>
    <style>
        /* CONFIGURACIÓN DE PÁGINA PARA PDF (LEGAL / OFICIO) */
        @page {
