            print-color-adjust: exact;
            width: 8.5in; 
            margin: 0 auto;
        }

        .page-container {
            width: 100%;
            height: 14in; 
            position: relative;
            background: white;
            padding: 50px; 
            page-break-after: always; 
            overflow: hidden; 
            display: flex;
            flex-direction: column;
        }

        /* --- ESTILOS GENERALES --- */
        .cover { background: linear-gradient(135deg, #FFD700 0%, #FFA500 100%); text-align: center; justify-content: center; align-items: center; }
        .cover h1 { font-size: 3.8em; color: #1a1a1a; margin-bottom: 20px; text-transform: uppercase; letter-spacing: 3px; line-height: 1.1; }
        .cover h2 { font-size: 2em; color: #2d2d2d; margin-bottom: 40px; font-weight: 400; }
        .cover .client-name { font-size: 2.2em; color: #1a1a1a; margin: 30px 0; font-weight: 700; border-top: 3px solid #1a1a1a; border-bottom: 3px solid #1a1a1a; padding: 20px 0; display: inline-block; }
        .cover .period { font-size: 1.4em; color: #2d2d2d; margin-top: 20px; }

        .section-header-wrapper { text-align: center; margin-bottom: 40px; flex-shrink: 0; }
        .section-title { font-size: 2.5em; color: #1a1a1a; margin-bottom: 10px; position: relative; padding-bottom: 15px; border-bottom: 4px solid #FFD700; display: inline-block; }

        .dashboard-content { flex-grow: 1; display: flex; flex-direction: column; justify-content: flex-start; gap: 40px; }
        .metric-card { background: #fff; padding: 35px; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); border: 1px solid #eee; border-top: 6px solid #FFD700; }
