                <span style="font-size: 1.2em; color: #666; display: block; margin-bottom: 5px;">Inversión Total Ejecutada</span>
                <div style="font-size: 4.5em; font-weight: 800; color: #1a1a1a; letter-spacing: -2px;">$${metrics.total.spend.toLocaleString('en-US', {minimumFractionDigits: 2})}</div>
            </div>
        </div>

        <div class="dashboard-content">
            <!-- PERFORMANCE CARD -->
            <div class="metric-card">
                <div class="card-header">
                    <div class="card-title" style="border-left: 6px solid #059669; padding-left: 15px;">Conversiones</div>
                    <div class="card-icon" style="font-size: 2em;">🎯</div>
                </div>
                <div class="kpi-row">
                    <div>
                        <div class="kpi-main-val color-perf">${metrics.performance.results}</div>
                        <div class="kpi-label">Resultados Clave</div>
                    </div>
                    <div class="kpi-secondary">
                        <div class="kpi-sec-val">$${realCPA.toFixed(2)}</div>
                        <div class="kpi-sec-label">Costo Promedio</div>
                    </div>
                </div>
                <div class="invest-box">
                    <span><strong>Inversión:</strong> $${metrics.performance.spend.toFixed(2)}</span>
                    <span>${metrics.total.spend > 0 ? ((metrics.performance.spend / metrics.total.spend)*100).toFixed(0) : 0}% del Budget</span>
                </div>
            </div>

            <!-- BRANDING CARD -->
            <div class="metric-card">
                <div class="card-header">
                    <div class="card-title" style="border-left: 6px solid #2563eb; padding-left: 15px;">Visibilidad de Marca</div>
                    <div class="card-icon" style="font-size: 2em;">👀</div>
                </div>
                <div class="kpi-row">
                    <div>
                        <div class="kpi-main-val color-brand">${(metrics.total.reach / 1000).toFixed(1)}k</div>
                        <div class="kpi-label">Alcance Total Cuenta</div>
                    </div>
                    <div class="kpi-secondary">
                        <div class="kpi-sec-val">$${accountCPM.toFixed(2)}</div>
                        <div class="kpi-sec-label">CPM Global</div>
                    </div>
                </div>
                <div class="invest-box">
                    <span><strong>Inversión Branding Puro:</strong> $${metrics.awareness.spend.toFixed(2)}</span>
                    <span>${metrics.total.spend > 0 ? ((metrics.awareness.spend / metrics.total.spend)*100).toFixed(0) : 0}% del Budget</span>
                </div>
            </div>
        </div>
    </div>

    <!-- PÁGINA 3: INSIGHTS ESTRATÉGICOS -->
    <div class="page-container">
        <div class="section-header-wrapper">
            <h2 class="section-title">💡 Análisis Estratégico</h2>
        </div>

        <div class="insights-grid">
            <div class="insight-card">
                <h3>🏆 Top Performer</h3>
                <p>${aiInsights.best_performance_text}</p>
            </div>
            <div class="insight-card">
                <h3>📊 Análisis de Volumen</h3>
                <p>${aiInsights.volume_text}</p>
            </div>
            <div class="insight-card">
                <h3>🔄 Estrategia de Embudo</h3>
                <p>${aiInsights.funnel_text}</p>
            </div>
        </div>
    </div>

    <!-- PÁGINA 4: METODOLOGÍA (FASES ACTIVAS) -->
    <div class="page-container">
        <div class="section-header-wrapper">
            <h2 class="section-title">🚀 Metodología Activa</h2>
        </div>

        <div class="phases-container">
            ${activePhasesHTML}
        </div>
    </div>

    <!-- PÁGINA 5: TABLA DETALLADA -->
    <div class="page-container">
        <div class="section-header-wrapper">
            <h2 class="section-title">🎯 Desglose Detallado</h2>
        </div>

        <div class="campaigns-table">
            <table>
                <thead>
                    <tr>
                        <th style="width: 35%">Campaña</th>
                        <th>Estrategia</th>
                        <th>Resultado</th>
                        <th>Costo (CPR)</th>
                        <th>Gasto</th>
                    </tr>
                </thead>
                <tbody>
                    ${tableRowsHTML}
                </tbody>
            </table>
        </div>

        <div class="cta-section">
            <h2>🎯 Continuemos Creciendo</h2>
            <p>Optimizando cada dólar invertido para ${CLIENT_NAME}.</p>
        </div>
    </div>

</body>
</html>
